package com.campus.student.application;
import java.time.Clock; import java.util.*; import com.campus.identity.application.IdentityUserDirectory; import com.campus.organization.application.OrganizationUnitManagementService; import com.campus.organization.domain.OrganizationUnitStatus; import com.campus.student.domain.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class StudentManagementService { private final StudentRepository students; private final OrganizationUnitManagementService organizations; private final IdentityUserDirectory identityUsers; private final Clock clock; private final com.campus.shared.application.PeopleRegistryAudit audits; public StudentManagementService(StudentRepository s,OrganizationUnitManagementService o,IdentityUserDirectory i,Clock c,com.campus.shared.application.PeopleRegistryAudit a){students=s;organizations=o;identityUsers=i;clock=c;audits=a;} @Transactional public Student create(String number,String name,String email,UUID identityUserId,UUID unit,StudentStatus status){return create(null,number,name,email,identityUserId,unit,status);} @Transactional public Student create(UUID actorId,String number,String name,String email,UUID identityUserId,UUID unit,StudentStatus status){validateUnit(unit);validateIdentityUser(identityUserId); Student s;try{s=Student.create(UUID.randomUUID(),number,name,email,identityUserId,unit,status==null?StudentStatus.ACTIVE:status,clock.instant());}catch(Student.InvalidStudentException e){throw new RequestValidationException();}if(students.existsByStudentNumber(s.studentNumber()))throw new StudentNumberAlreadyExistsException();Student saved;try{saved=students.save(s);}catch(DataIntegrityViolationException e){throw new StudentNumberAlreadyExistsException();}if(actorId!=null)audits.record(actorId,"STUDENT",saved.id(),"CREATED",clock.instant());return saved;} @Transactional(readOnly=true) public Student get(UUID id){return students.findById(id).orElseThrow(StudentNotFoundException::new);} @Transactional(readOnly=true) public List<Student> list(){return students.findAll();} @Transactional(readOnly=true) public com.campus.shared.application.PageResult<Student> search(StudentSearch search){return students.search(search);} @Transactional public Student update(UUID id,String n,String name,String email,UUID identityUserId,UUID unit,StudentStatus status,long version){return update(null,id,n,name,email,identityUserId,unit,status,version);} @Transactional public Student update(UUID actorId,UUID id,String n,String name,String email,UUID identityUserId,UUID unit,StudentStatus status,long version){Student old=get(id);validateUnit(unit);validateIdentityUser(identityUserId);Student next;try{next=new Student(id,n,name,email,identityUserId,unit,status,old.rowVersion(),old.createdAt(),clock.instant());}catch(Student.InvalidStudentException e){throw new RequestValidationException();}Student saved;try{saved=students.saveMutation(next,version);}catch(NoSuchElementException e){throw new StudentNotFoundException();}catch(DataIntegrityViolationException e){throw new StudentNumberAlreadyExistsException();}if(actorId!=null)audits.record(actorId,"STUDENT",saved.id(),"UPDATED",clock.instant());return saved;} private void validateUnit(UUID id){try{if(organizations.get(id).status()!=OrganizationUnitStatus.ACTIVE)throw new OrganizationUnitUnavailableException();}catch(OrganizationUnitManagementService.OrganizationUnitNotFoundException e){throw new OrganizationUnitUnavailableException();}} private void validateIdentityUser(UUID id){if(id!=null&&!identityUsers.exists(id))throw new IdentityUserUnavailableException();} public static final class StudentNotFoundException extends RuntimeException{} public static final class StudentNumberAlreadyExistsException extends RuntimeException{} public static final class ConcurrentStudentModificationException extends RuntimeException{} public static final class OrganizationUnitUnavailableException extends RuntimeException{} public static final class IdentityUserUnavailableException extends RuntimeException{} public static final class RequestValidationException extends RuntimeException{} }
